            setGameState(prev => ({ 
                ...prev, 
                currentSceneImageUrl: url,
                sceneHistory: [...(prev.sceneHistory || []), { imageUrl: url, location: locationName, description: textData.description, timestamp: Date.now() }] 
            }));
