    const style = RPG_ADVENTURE_STYLES.find(s => s.id === selectedStyleId);
    const prompt = `GM Logic (${style?.name}). Location: ${gameState.currentLocation}. Action: "${actionLabel}". Entropy: ${currentEntropy}.
