    if (!name.trim()) { alert("A Seeker must have a name."); return; }
    setStep('weaving');
    globalSoundEngine.playSFX('pulse');
    try {
        const bioPrompt = `Synthesize a unique bio for ${name} (${race} ${seekerClass}). Intention: "${intent || 'Unknown'}". 2 sentences. Return JSON: {"bio": "..."}`;
        const response = await invokeGemini(bioPrompt, "Output JSON only.", "application/json");
