        AURA: Intense ${aura} primary aura with ${secondaryAura} flickering secondary resonance. 
        STYLE: ${visualFilter} aesthetic rendering, high detail, no text in image.`;

        const avatarUrlResult = await generateImage(imagePrompt, 'gemini-2.5-flash-image');

        const auraEnum = SEEKER_AURA_OPTIONS.find(o => o.hex.toLowerCase() === aura.toLowerCase())?.id as SeekerAuraColor || SeekerAuraColor.Prismatic;
        const secAuraEnum = SEEKER_AURA_OPTIONS.find(o => o.hex.toLowerCase() === secondaryAura.toLowerCase())?.id as SeekerAuraColor || SeekerAuraColor.Prismatic;

        const finalProfile: SeekerProfile = { 
            generatedAt: Date.now(), 
            level: 1, 
            experience: 0, 
            flux: 100, 
            inventory: [activeWeapon, activeOutfit], 
            selfTraits: ["Calibrated"], 
            codexTraits: ["Seeker"], 
            name: name || "Anonymous", 
            race, 
            class: seekerClass, 
            gender, 
