            auraSecondaryColor: secAuraEnum, 
            visualFilter, 
            avatarImageUrl: avatarUrlResult || "", 
            bio: data.bio || "A Seeker entering the Codex.", 
            equippedWeapon: activeWeapon, 
            equippedOutfit: activeOutfit 
        };

        setGeneratedProfile(finalProfile);
        setStep('reveal');
        globalSoundEngine.playSFX('success');
    } catch (e) { 
        console.error("Weaving Error:", e);
        setGeneratedProfile({
            generatedAt: Date.now(),
            level: 1, experience: 0, flux: 100,
            inventory: [activeWeapon, activeOutfit],
