export const ParallaxParticles: React.FC<{ scrollY: number }> = ({ scrollY }) => {
  const canvasRef = useRef<HTMLCanvasElement>(null);
  const particles = useRef<Particle[]>([]);
  const animationFrameRef = useRef<number>(0);

  useEffect(() => {
    const canvas = canvasRef.current;
    if (!canvas) return;
    const ctx = canvas.getContext('2d');
    if (!ctx) return;

    const resize = () => {
      canvas.width = window.innerWidth;
      canvas.height = window.innerHeight;
    };
    window.addEventListener('resize', resize);
    resize();

    // Initialize particles
    const count = 60;
    particles.current = Array.from({ length: count }, () => ({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      z: Math.random() * 0.5 + 0.1, // Depth factor
      size: Math.random() * 2 + 1,
      speed: Math.random() * 0.2 + 0.05,
      opacity: Math.random() * 0.5 + 0.1,
      hue: Math.random() > 0.5 ? 190 : 280, // Cyan or Violet
    }));

    const animate = () => {
      ctx.clearRect(0, 0, canvas.width, canvas.height);
      ctx.globalCompositeOperation = 'lighter';

      particles.current.forEach(p => {
        // Vertical drift + scroll parallax
        const effectiveY = (p.y - (scrollY * p.z)) % canvas.height;
        const drawY = effectiveY < 0 ? effectiveY + canvas.height : effectiveY;

        // Horizontal oscillation
        const drawX = p.x + Math.sin(Date.now() * 0.001 * p.speed) * 20;

        ctx.beginPath();
        ctx.arc(drawX, drawY, p.size, 0, Math.PI * 2);
        ctx.fillStyle = `hsla(${p.hue}, 80%, 70%, ${p.opacity})`;
        ctx.shadowBlur = 10;
        ctx.shadowColor = `hsla(${p.hue}, 80%, 70%, 1)`;
        ctx.fill();

        // Connections for "constellation" feel at low scroll
        if (scrollY < 100) {
            ctx.shadowBlur = 0;
            particles.current.forEach(p2 => {
               const dX = p2.x - p.x;
               const dY = p2.y - p.y;
               const dist = Math.sqrt(dX*dX + dY*dY);
               if (dist < 150) {
                   ctx.beginPath();
                   ctx.moveTo(drawX, drawY);
                   ctx.lineTo(p2.x + Math.sin(Date.now() * 0.001 * p2.speed) * 20, (p2.y - (scrollY * p2.z)) % canvas.height);
                   ctx.strokeStyle = `hsla(${p.hue}, 80%, 70%, ${0.1 * (1 - dist/150)})`;
                   ctx.stroke();
               }
            });
        }
      });

      animationFrameRef.current = requestAnimationFrame(animate);
    };

    animate();
    return () => {
      window.removeEventListener('resize', resize);
      cancelAnimationFrame(animationFrameRef.current);
    };
  }, [scrollY]);

  return (
    <canvas 
      ref={canvasRef} 
      className="fixed inset-0 pointer-events-none z-0"
      style={{ opacity: Math.max(0.2, 1 - scrollY / 1000) }}
    />
  );
};

