                                            </motion.div>
                                        ))}
                                        {isProcessingTurn && <div className="text-indigo-400 animate-pulse font-mono text-[10px] uppercase">Processing...</div>}
                                    </div>

                                    <div className="flex flex-col gap-2">
                                        {gameState.availableActions.map((act, i) => (
