                                </motion.div>
                            ) : (
                                <motion.div key="archive" initial={{ opacity: 0, y: 20 }} animate={{ opacity: 1, y: 0 }} exit={{ opacity: 0, y: -20 }} className="w-full">
                                     <RPGMementoArchivePanel 
