                                        narrativeHistory={gameState.narrativeHistory} 
                                        activeProfile={activeProfile} 
                                        currentEntropy={currentEntropy} 
                                        addEchoMessage={addEchoMessage} 
                                    />
                                </motion.div>
                            )}
                        </AnimatePresence>
                    </div>
                </div>
            </div>
        )}
    </div>
  );
};

