                />
                <SeekerVitalsPanel activeProfile={activeProfile} rpgState={rpgState} />
                <CommunityResonancePanel addEchoMessage={addEchoMessage} seekerFaction={activeProfile?.faction} />
                <ProtocolDuelPanel width="100%" height={500} activeProfile={activeProfile} onUpdateProfile={handleUpdateProfile} addEchoMessage={addEchoMessage} />
            </aside>

            <section className="lg:col-span-6 flex flex-col gap-8 order-1 lg:order-2">
              {activeProfile && (
                <SeekerProfileDashboardPanel 
