import React, { createContext, useState, useCallback, useContext, ReactNode } from 'react';
import { GoogleGenAI, GenerateContentResponse, Modality } from "@google/genai"; 
import type { GeminiContextType } from '../types';

const GeminiContext = createContext<GeminiContextType | undefined>(undefined);

function decodeBase64(base64: string): Uint8Array {
  try {
    const binaryString = atob(base64);
    const len = binaryString.length;
    const bytes = new Uint8Array(len);
    for (let i = 0; i < len; i++) {
      bytes[i] = binaryString.charCodeAt(i);
    }
    return bytes;
  } catch (e) {
    console.error("Base64 decoding failed:", e);
    return new Uint8Array(0);
  }
}

export const GeminiProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [isGenerating, setIsGenerating] = useState(false);
  const [error, setError] = useState<Error | null>(null);
  const [lastGeminiResponseText, setLastGeminiResponseText] = useState<string | null>(null);

  const getAiClient = useCallback(() => {
    // Defensive check for process existence
    const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : (window as any).process?.env?.API_KEY;

    if (!apiKey) {
        console.error("API Key missing from environment. Oracle functionality will be limited.");
        return null;
    }
    try {
      return new GoogleGenAI({ apiKey });
    } catch (e) {
      console.error("Error creating GoogleGenAI client:", e);
      return null;
    }
  }, []);

  const invokeGemini = useCallback(async (prompt: string, systemInstruction?: string, responseMimeType?: "text/plain" | "application/json"): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return "System error: Oracle connection offline.";

    setIsGenerating(true);
    setError(null);

    try {
      const response: GenerateContentResponse = await ai.models.generateContent({
        model: 'gemini-3-flash-preview', 
        contents: prompt,
        config: {
            ...(systemInstruction && { systemInstruction }),
            ...(responseMimeType && { responseMimeType })
        }
      });

      const text = response.text || "The Oracle remains silent."; 
      setLastGeminiResponseText(text);
      setIsGenerating(false);
      return text;
    } catch (e: any) {
      console.error("Gemini API Error (text):", e);
      setError(e instanceof Error ? e : new Error('API communication failure'));
      setIsGenerating(false);
      return "An entropic shadow has blocked the transmission.";
    }
  }, [getAiClient]);

  const generateImage = useCallback(async (prompt: string, model: 'imagen-4.0-generate-001' | 'gemini-2.5-flash-image' = 'gemini-2.5-flash-image', referenceImage?: string): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return null;

    setIsGenerating(true);
    setError(null);

    try {
      if (model === 'gemini-2.5-flash-image') {
         const parts: any[] = [{ text: prompt }];
         if (referenceImage) {
            const base64Data = referenceImage.includes(',') ? referenceImage.split(',')[1] : referenceImage;
            parts.unshift({
                inlineData: { data: base64Data, mimeType: 'image/png' }
            });
         }

         const response = await ai.models.generateContent({
            model: 'gemini-2.5-flash-image',
            contents: { parts },
         });

         const imagePart = response.candidates?.[0]?.content?.parts?.find(p => p.inlineData);
         if (imagePart?.inlineData) {
            const imageUrl = `data:${imagePart.inlineData.mimeType || 'image/png'};base64,${imagePart.inlineData.data}`;
            setIsGenerating(false);
            return imageUrl;
         }
         throw new Error("No image data returned.");
      } else {
          const response = await ai.models.generateImages({
            model: model,
            prompt: prompt,
            config: { numberOfImages: 1, outputMimeType: 'image/png' },
          });

          if (response.generatedImages?.[0]?.image?.imageBytes) {
            const imageUrl = `data:image/png;base64,${response.generatedImages[0].image.imageBytes}`;
            setIsGenerating(false);
            return imageUrl;
          }
          throw new Error('Image generation empty.');
      }
    } catch (e: any) {
      console.error("Gemini API Error (image):", e);
      setError(e instanceof Error ? e : new Error('Visual synthesis failed'));
      setIsGenerating(false);
      return null;
    }
  }, [getAiClient]);

  const generateVideo = useCallback(async (prompt: string, imageBase64?: string): Promise<string | null> => {
    const ai = getAiClient();
    if (!ai) return null;

    setIsGenerating(true);
    try {
        const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : (window as any).process?.env?.API_KEY;
        let operation = await ai.models.generateVideos({
            model: 'veo-3.1-fast-generate-preview',
            prompt, 
            ...(imageBase64 && {
                image: {
                    imageBytes: imageBase64.includes(',') ? imageBase64.split(',')[1] : imageBase64,
                    mimeType: 'image/png', 
                }
            }),
            config: { numberOfVideos: 1, resolution: '720p', aspectRatio: '16:9' }
        });

        while (!operation.done) {
            await new Promise(resolve => setTimeout(resolve, 5000));
            operation = await ai.operations.getVideosOperation({ operation });
        }

        const videoUri = operation.response?.generatedVideos?.[0]?.video?.uri;
        if (videoUri) {
            const fetchUrl = `${videoUri}&key=${apiKey}`;
            const videoResponse = await fetch(fetchUrl);
            const videoBlob = await videoResponse.blob();
            setIsGenerating(false);
            return URL.createObjectURL(videoBlob);
        }
        throw new Error("Video URI missing.");
    } catch (e: any) {
        console.error("Gemini API Error (video):", e);
        setIsGenerating(false);
        return null;
    }
  }, [getAiClient]);

  const generateSpeech = useCallback(async (text: string, voiceName: string = 'Kore'): Promise<ArrayBuffer | null> => {
    const ai = getAiClient();
    if (!ai || !text?.trim()) return null;

    try {
      const safeText = text.substring(0, 1000);
      const response = await ai.models.generateContent({
        model: "gemini-2.5-flash-preview-tts",
        contents: [{ parts: [{ text: `Say clearly and mystically: ${safeText}` }] }],
        config: {
          responseModalities: [Modality.AUDIO],
          speechConfig: { voiceConfig: { prebuiltVoiceConfig: { voiceName } } },
        },
      });

      const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
      return base64Audio ? decodeBase64(base64Audio).buffer : null;
    } catch (e: any) {
      console.error("Gemini Speech Error:", e);
      return null;
    }
  }, [getAiClient]);

  return (
    <GeminiContext.Provider value={{ isGenerating, error, lastGeminiResponseText, invokeGemini, generateImage, generateVideo, generateSpeech }}>
      {children}
    </GeminiContext.Provider>
  );
};

export const useGemini = (): GeminiContextType => {
  const context = useContext(GeminiContext);
  if (context === undefined) throw new Error('useGemini must be used within a GeminiProvider');
  return context;
};

import React, { createContext, useContext, useState, useCallback, useRef } from 'react';
import { useGemini } from './GeminiIntegrationContext';
import { globalPCMPlayer } from '../lib/narration/PCMPlayer';
import { Modality } from '@google/genai';

interface NarrationContextType {
  isNarrationEnabled: boolean;
  toggleNarration: () => void;
  speak: (text: string, voiceName?: string) => Promise<void>;
}

const NarrationContext = createContext<NarrationContextType | undefined>(undefined);

export const NarrationProvider: React.FC<{ children: React.ReactNode }> = ({ children }) => {
  const [isNarrationEnabled, setIsNarrationEnabled] = useState(true);
  const queueRef = useRef<Promise<void>>(Promise.resolve());

  const speak = useCallback(async (text: string, voiceName: string = 'Kore') => {
    if (!isNarrationEnabled || !text) return;

    const apiKey = typeof process !== 'undefined' && process.env ? process.env.API_KEY : (window as any).process?.env?.API_KEY;

    // Add to serial queue to prevent overlapping speech
    queueRef.current = queueRef.current.then(async () => {
      try {
        if (!apiKey) throw new Error("API Key missing");

        const { GoogleGenAI } = await import('@google/genai');
        const ai = new GoogleGenAI({ apiKey });
        const response = await ai.models.generateContent({
          model: "gemini-2.5-flash-preview-tts",
          contents: [{ parts: [{ text: `Read this clearly: ${text}` }] }],
          config: {
            responseModalities: [Modality.AUDIO],
            speechConfig: {
              voiceConfig: {
                prebuiltVoiceConfig: { voiceName },
              },
            },
          },
        });

        const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
        if (base64Audio) {
          await globalPCMPlayer.play(base64Audio);
        } else {
          throw new Error("No audio data");
        }
      } catch (e) {
        console.warn("Gemini TTS failed, falling back to WebSpeech", e);
        return new Promise<void>((resolve) => {
          const utterance = new SpeechSynthesisUtterance(text);
          utterance.onend = () => resolve();
          window.speechSynthesis.speak(utterance);
        });
      }
    });

    return queueRef.current;
  }, [isNarrationEnabled]);

  const toggleNarration = () => {
    const newState = !isNarrationEnabled;
    setIsNarrationEnabled(newState);
    if (!newState) {
      window.speechSynthesis.cancel();
      globalPCMPlayer.stopAll();
    } else {
      speak("Narration protocol initialized. I will read incoming data streams for you.");
    }
  };

  return (
    <NarrationContext.Provider value={{ isNarrationEnabled, toggleNarration, speak }}>
      {children}
    </NarrationContext.Provider>
  );
};

export const useNarration = () => {
  const context = useContext(NarrationContext);
  if (!context) throw new Error("useNarration must be used within NarrationProvider");
  return context;
};

