import { GoogleGenAI, Type } from "@google/genai";
import { AgentPlan, ProjectMetadata, SovereignPhase, SeekerProfile } from '../types';
import { driftDB } from '../db';

export class SovereignKernel {
    private ai: GoogleGenAI;
    private modelName = 'gemini-3-pro-preview';

    constructor() {
        const apiKey = process.env.API_KEY || (window as any).process?.env?.API_KEY;
        this.ai = new GoogleGenAI({ apiKey });
    }

    /**
     * RESEARCH PHASE: Grounded search for specific goals.
     */
    async researchGoal(goal: string): Promise<{ summary: string; sources: any[] }> {
        const response = await this.ai.models.generateContent({
            model: this.modelName,
            contents: `Conduct deep research into the following objective: "${goal}". Provide a comprehensive summary and identify key digital artifacts to create.`,
            config: {
                tools: [{ googleSearch: {} }]
            }
        });

        return {
            summary: response.text || "No research data found.",
            sources: response.candidates?.[0]?.groundingMetadata?.groundingChunks || []
        };
    }

    /**
     * PLANNING PHASE: Structured step generation.
     */
    async generatePlan(goal: string, research: string): Promise<AgentPlan> {
        const response = await this.ai.models.generateContent({
            model: this.modelName,
            contents: `Goal: ${goal}\nResearch: ${research}\nCreate a structured project plan with specific tasks.`,
            config: {
                responseMimeType: "application/json",
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        objective: { type: Type.STRING },
                        steps: {
                            type: Type.ARRAY,
                            items: {
                                type: Type.OBJECT,
                                properties: {
                                    id: { type: Type.STRING },
                                    description: { type: Type.STRING },
                                    tool: { type: Type.STRING },
                                    status: { type: Type.STRING }
                                }
                            }
                        }
                    },
                    required: ["objective", "steps"]
                }
            }
        });

        return JSON.parse(response.text || '{}') as AgentPlan;
    }

    /**
     * CREATION PHASE: provision VM and write files.
     */
    async provisionVM(projectName: string): Promise<string> {
        const projectId = `vm-${Date.now()}`;
        const newProject: ProjectMetadata = {
            id: projectId,
            name: projectName,
            description: "Angelic Workflow Instance",
            createdAt: Date.now(),
            vmStatus: 'Active',
            files: [
                { path: 'active_plan.json', content: '{}', lastModified: Date.now() },
                { path: 'manifest.txt', content: `Project ${projectName} Initialized.`, lastModified: Date.now() }
            ]
        };

        // Persist to Dexie KV store
        const existingProjects = await driftDB.loadAppState('sovereign_projects') || [];
        await driftDB.saveAppState('sovereign_projects', [...existingProjects, newProject]);

        return projectId;
    }

    async writeProjectFile(projectId: string, path: string, content: string): Promise<void> {
        const projects = await driftDB.loadAppState('sovereign_projects') as ProjectMetadata[] || [];
        const index = projects.findIndex(p => p.id === projectId);
        if (index !== -1) {
            const fileIndex = projects[index].files.findIndex(f => f.path === path);
            if (fileIndex !== -1) {
                projects[index].files[fileIndex].content = content;
                projects[index].files[fileIndex].lastModified = Date.now();
            } else {
                projects[index].files.push({ path, content, lastModified: Date.now() });
            }
            await driftDB.saveAppState('sovereign_projects', projects);
        }
    }
}

