interface ChatNVKPanelProps {
    activeProfile: SeekerProfile | null;
    addEchoMessage: (s: string, t: string, c: string) => void;
}

export const ChatNVKPanel: React.FC<ChatNVKPanelProps> = ({ activeProfile, addEchoMessage }) => {
    const [messages, setMessages] = useState<{sender: string, text: string, type: 'user' | 'bot'}[]>([]);
    const [input, setInput] = useState("");
    const [phase, setPhase] = useState<SovereignPhase>(SovereignPhase.IDLE);
    const [activePlan, setActivePlan] = useState<AgentPlan | null>(null);
    const [isThinking, setIsThinking] = useState(false);

    const scrollRef = useRef<HTMLDivElement>(null);
    const { invokeGemini } = useGemini();

    useEffect(() => {
        if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
    }, [messages, phase]);

    const runAngelicWorkflow = async (goal: string) => {
        if (!goal.trim() || isThinking) return;
        setIsThinking(true);
        setMessages(prev => [...prev, { sender: activeProfile?.name || 'Seeker', text: goal, type: 'user' }]);

        try {
            // 1. RESEARCH
            setPhase(SovereignPhase.RESEARCH);
            globalSoundEngine.playSFX('pulse');
            const research = await globalSovereignKernel.researchGoal(goal);
            setMessages(prev => [...prev, { sender: 'ChatNVK', text: `Research Complete. Foundations laid: ${research.summary.substring(0, 150)}...`, type: 'bot' }]);

            // 2. PLANNING
            setPhase(SovereignPhase.PLANNING);
            const plan = await globalSovereignKernel.generatePlan(goal, research.summary);
            setActivePlan(plan);
            setMessages(prev => [...prev, { sender: 'ChatNVK', text: `Project Architecture generated. Objectives: ${plan.steps.length} steps defined.`, type: 'bot' }]);

            // 3. CREATION (Firecracker VM)
            setPhase(SovereignPhase.CREATION);
            const projectId = await globalSovereignKernel.provisionVM(plan.objective.substring(0, 15));
            setMessages(prev => [...prev, { sender: 'ChatNVK', text: `Firecracker VM Instance Provisioned: ${projectId}. Writing sacred code...`, type: 'bot' }]);

            for (const step of plan.steps) {
                await globalSovereignKernel.writeProjectFile(projectId, `${step.id}.txt`, `Result of ${step.description}`);
                await new Promise(r => setTimeout(r, 1000));
            }

            // 4. AUDIT
            setPhase(SovereignPhase.AUDIT);
            setMessages(prev => [...prev, { sender: 'ChatNVK', text: "Final Audit: Creation aligns with Tri-Sophian Axioms. Project Complete.", type: 'bot' }]);

        } catch (e) {
            setMessages(prev => [...prev, { sender: 'System', text: "Workflow cascade failure. Neural link unstable.", type: 'bot' }]);
        } finally {
            setIsThinking(false);
            setPhase(SovereignPhase.IDLE);
        }
    };

    return (
        <div className="flex h-full w-full bg-slate-950 border border-indigo-500/30 rounded-3xl overflow-hidden shadow-2xl relative">
            {/* Sidebar: Angelic Plan & Project */}
            <div className="w-80 bg-slate-900/50 border-r border-white/10 p-4 flex flex-col gap-6 backdrop-blur-md">
                <div className="space-y-4">
                    <h3 className="text-xs font-cinzel font-bold text-indigo-400 uppercase tracking-widest border-b border-indigo-900/50 pb-2 flex justify-between">
                        Angelic Workflow
                        <span className="text-emerald-400">{phase}</span>
                    </h3>
                    <div className="space-y-2 max-h-60 overflow-y-auto custom-scrollbar">
                        {activePlan?.steps.map(step => (
                            <div key={step.id} className="p-2 rounded bg-white/5 border border-white/10 text-[10px] flex items-center gap-2">
                                <i className={`ri-${step.status === 'done' ? 'checkbox-circle-fill text-emerald-400' : 'time-line text-slate-500'}`}></i>
                                <span className="text-slate-300 truncate">{step.description}</span>
                            </div>
                        ))}
                        {!activePlan && <p className="text-[10px] text-slate-500 italic">No active plan.</p>}
                    </div>
                </div>

                <div className="space-y-4 mt-auto">
                    <h3 className="text-xs font-cinzel font-bold text-amber-400 uppercase tracking-widest border-b border-amber-900/50 pb-2">
                        Firecracker VM
                    </h3>
                    <div className="p-3 rounded-xl bg-black/40 border border-white/5 font-mono text-[9px] text-emerald-500/80">
                        <p>> status: {phase === SovereignPhase.CREATION ? 'PROVISIONING' : 'READY'}</p>
                        <p>> entropy: 0.12δ</p>
                        <p>> containers: 1 active</p>
                    </div>
                </div>
            </div>

            {/* Main Chat Area */}
            <div className="flex-grow flex flex-col min-w-0">
                <header className="p-4 border-b border-white/5 bg-slate-900/30 flex items-center justify-between">
                    <div className="flex items-center gap-3">
                        <div className="w-8 h-8 rounded-lg bg-indigo-600/20 border border-indigo-500/50 flex items-center justify-center">
                            <i className="ri-quill-pen-line text-indigo-400"></i>
                        </div>
                        <h2 className="font-cinzel font-bold text-white tracking-widest uppercase text-sm">ChatNVK // Codex Interface</h2>
                    </div>
                </header>

                <div ref={scrollRef} className="flex-grow p-6 overflow-y-auto space-y-6 custom-scrollbar bg-slate-950/20">
                    <AnimatePresence>
                        {messages.map((m, i) => (
                            <motion.div 
                                key={i}
                                initial={{ opacity: 0, y: 10 }}
                                animate={{ opacity: 1, y: 0 }}
                                className={`flex ${m.type === 'user' ? 'justify-end' : 'justify-start'}`}
                            >
                                <div className={`max-w-[80%] p-4 rounded-2xl border text-sm leading-relaxed ${
                                    m.type === 'user' 
                                    ? 'bg-indigo-900/20 border-indigo-500/30 text-indigo-100 rounded-tr-none' 
                                    : 'bg-slate-900/60 border-white/10 text-slate-200 rounded-tl-none italic font-cormorant'
                                }`}>
                                    <div className="text-[10px] font-mono text-slate-500 mb-1 uppercase tracking-tighter">{m.sender}</div>
                                    {m.text}
                                </div>
                            </motion.div>
                        ))}
                    </AnimatePresence>
                    {isThinking && (
                        <div className="flex gap-1 items-center p-4">
                            <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '0ms' }} />
                            <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '200ms' }} />
                            <div className="w-1.5 h-1.5 bg-indigo-500 rounded-full animate-bounce" style={{ animationDelay: '400ms' }} />
                            <span className="text-[10px] font-mono text-indigo-400 ml-2 uppercase tracking-widest">Neural Weft Processing...</span>
                        </div>
                    )}
                </div>

                <div className="p-4 bg-slate-900/50 border-t border-white/5">
                    <div className="flex gap-3 max-w-4xl mx-auto">
                        <textarea 
                            value={input}
                            onChange={(e) => setInput(e.target.value)}
                            onKeyDown={(e) => e.key === 'Enter' && !e.shiftKey && (e.preventDefault(), runAngelicWorkflow(input), setInput(""))}
                            placeholder="Initialize Angelic Workflow (Research, Plan, Create...)"
                            className="flex-grow bg-slate-800/50 border border-white/10 rounded-2xl p-4 text-sm text-slate-100 focus:outline-none focus:border-indigo-500/50 resize-none h-14 custom-scrollbar"
                        />
                        <button 
                            onClick={() => { runAngelicWorkflow(input); setInput(""); }}
                            disabled={isThinking || !input.trim()}
                            className="w-14 h-14 rounded-2xl bg-indigo-600 hover:bg-indigo-500 text-white flex items-center justify-center shadow-xl transition-all active:scale-95 disabled:opacity-50"
                        >
                            <i className="ri-send-plane-2-fill text-xl"></i>
                        </button>
                    </div>
                </div>
            </div>
        </div>
    );
};

